   565→function setServerStatus(online) {
   566→    if (!statusDot || !statusText) return;
   567→    if (online) {
   568→        statusDot.classList.remove('offline');
   569→        statusText.textContent = 'Online';
   570→    } else {
   571→        statusDot.classList.add('offline');
   572→        statusText.textContent = 'Offline';
   573→    }
   574→}
   575→
   576→window.setServerStatus = setServerStatus;
