   578→async function api(path, method = 'GET', body) {
   579→    const options = {
   580→        method,
   581→        headers: {'Content-Type': 'application/json'}
   582→    };
   583→    if (body) {
   584→        options.body = JSON.stringify(body);
   585→    }
   586→    try {
   587→        const response = await fetch(path, options);
   588→        if (!response.ok) {
   589→            throw new Error(response.status + ' ' + response.statusText);
   590→        }
   591→        const data = await response.json();
   592→        setServerStatus(true);
   593→        return data;
   594→    } catch (error) {
   595→        setServerStatus(false);
   596→        throw error;
   597→    }
   598→}
