   869→        resp = await api('/api/room/actions', 'POST', {room});
   870→    } catch (error) {
   871→        console.warn('Nutze Fallback-Aktionen für "' + room + '".', error);
   872→        resp = {
   873→            battle: BATTLE_ROOMS.has(room),
   874→            actions: ROOM_ACTIONS_FALLBACK[room] || []
   875→        };
   876→    }
   877→    const wrap = document.getElementById('room-actions');
   878→    wrap.innerHTML = '';
   879→    const actions = resp && resp.actions ? resp.actions : ROOM_ACTIONS_FALLBACK[room] || [];
   880→    actions.forEach(a => {
   881→        const b = document.createElement('button');
   882→        b.className = 'action-btn';
   883→        b.textContent = a;
   884→        b.onclick = () => handleAction(room, a);
   885→        wrap.appendChild(b);
   886→    });
   887→    const battlePanel = document.getElementById('battlePanel');
   888→    if (battlePanel) {
   889→        if (!resp || !resp.battle) {
   890→            battlePanel.style.display = 'none';
   891→        }
   892→    }
   893→}
