else:
    print("[SKIP] CSS bereits vorhanden")

# Speichern
with open(INDEX_HTML, 'w', encoding='utf-8') as f:
    f.write(content)

print("\n[FERTIG] index.html gepatched!")
print("Starte Najika mit: START_NAJIKA.bat")

