   267→    function onPointerDown(event) {
   268→        if (!orbitCanvas) {
   269→            return;
   270→        }
   271→        event.preventDefault();
   272→        activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
   273→
   274→        if (activePointers.size === 1) {
   275→            // Single touch/click: Rotate
   276→            pointerMode = 'rotate';
   277→            dragStartPos = { x: event.clientX, y: event.clientY };
   278→            dragStartYaw = orbitYaw;
   279→            dragStartPitch = orbitPitch;
   280→        } else if (activePointers.size === 2 && cameraMode === CAMERA_MODES.ORBIT) {
   281→            // Two touches: Pinch to zoom (nur in Orbit)
   282→            pointerMode = 'pinch';
   283→            pinchStartDist = computePointerDistance();
   284→            pinchBaseDistance = orbitDistance;
   285→        }
   286→    }
   287→
   288→    function onPointerMove(event) {
   289→        if (!activePointers.has(event.pointerId)) {
   290→            return;
   291→        }
   292→        activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
   293→
   294→        if (pointerMode === 'pinch' && activePointers.size === 2 && cameraMode === CAMERA_MODES.ORBIT) {
   295→            const dist = computePointerDistance();
   296→            if (pinchStartDist > 0) {
   297→                const ratio = dist / pinchStartDist;
   298→                if (ratio > 0) {
   299→                    orbitDistance = clamp(pinchBaseDistance / ratio, ORBIT_MIN_DIST, ORBIT_MAX_DIST);
   300→                }
   301→            }
   302→        } else if (pointerMode === 'rotate' && activePointers.size === 1) {
   303→            const dx = event.clientX - dragStartPos.x;
   304→            const dy = event.clientY - dragStartPos.y;
   305→            orbitYaw = dragStartYaw - dx * 0.005;
   306→            orbitPitch = clamp(dragStartPitch - dy * 0.003, ORBIT_MIN_PITCH, ORBIT_MAX_PITCH);
   307→        }
   308→    }
   309→
   310→    function onPointerUp(event) {
   311→        activePointers.delete(event.pointerId);
   312→        if (activePointers.size === 0) {
   313→            pointerMode = null;
   314→        } else if (activePointers.size === 1 && pointerMode === 'pinch') {
   315→            // Switched from pinch back to rotate
   316→            pointerMode = 'rotate';
   317→            const remaining = Array.from(activePointers.values())[0];
   318→            dragStartPos = { x: remaining.x, y: remaining.y };
   319→            dragStartYaw = orbitYaw;
   320→            dragStartPitch = orbitPitch;
   321→        }
   322→    }
   323→
   324→    function onWheel(event) {
   325→        if (cameraMode !== CAMERA_MODES.ORBIT) {
   326→            return;
   327→        }
   328→        event.preventDefault();
   329→        const delta = Math.sign(event.deltaY) * 1.5;
   330→        orbitDistance = clamp(orbitDistance + delta, ORBIT_MIN_DIST, ORBIT_MAX_DIST);
   331→    }
