   333→    function computePointerDistance() {
   334→        const ptrs = Array.from(activePointers.values());
   335→        if (ptrs.length < 2) return 0;
   336→        const dx = ptrs[0].x - ptrs[1].x;
   337→        const dy = ptrs[0].y - ptrs[1].y;
   338→        return Math.sqrt(dx * dx + dy * dy);
   339→    }
