   474→    function roomAssetsAvailable(config) {
   475→        if (!window.KayKitLoader) {
   476→            return false;
   477→        }
   478→        const required = new Set();
   479→        if (config.floor && config.floor.model) required.add(config.floor.model);
   480→        if (config.walls && config.walls.model) required.add(config.walls.model);
   481→        if (Array.isArray(config.props)) {
   482→            config.props.forEach(prop => {
   483→                if (prop && prop.model) required.add(prop.model);
   484→            });
   485→        }
   486→        for (const name of required) {
   487→            if (!KayKitLoader.hasModel || !KayKitLoader.hasModel(name)) {
   488→                return false;
   489→            }
   490→        }
   491→        return true;
   492→    }
