   494→    function buildFloor(entry, span) {
   495→        const instance = makeModelInstance(entry);
   496→        if (!instance) return null;
   497→        // Skaliere Boden auf volle span-Größe
   498→        scaleUniformToSpan(instance, span);
   499→        // Mache Boden EXTREM flach (nur 5% Höhe) wie eine dünne Platte
   500→        instance.scale.y *= 0.05;
   501→        // Berechne BoundingBox um Boden korrekt zu positionieren
   502→        const box = new THREE.Box3().setFromObject(instance);
   503→        const floorHeight = box.max.y - box.min.y;
   504→        // Positioniere so dass OBERSEITE bei Y=0 ist (Unterseite darunter)
   505→        instance.position.y = -box.min.y - floorHeight;
   506→        applyEntryTransform(instance, entry);
   507→        return instance;
   508→    }
   509→
   510→    function buildWalls(entry, span, wallHeight) {
   511→        const base = makeModelInstance(entry);
   512→        if (!base) return null;
   513→
   514→        // Skaliere Wand-Modell auf die volle span-Breite
   515→        scaleAxisToSpan(base, 'x', span);
   516→
   517→        const group = new THREE.Group();
   518→        // Wände am RAND des Bodens positionieren (span / 2)
   519→        const half = span / 2;
   520→
   521→        const north = cloneGroup(base);
   522→        north.position.set(0, 0, -half);
   523→        group.add(north);
   524→
   525→        const south = cloneGroup(base);
   526→        south.rotation.y = Math.PI;
   527→        south.position.set(0, 0, half);
   528→        group.add(south);
   529→
   530→        const east = cloneGroup(base);
   531→        east.rotation.y = -Math.PI / 2;
   532→        east.position.set(half, 0, 0);
   533→        group.add(east);
   534→
   535→        const west = cloneGroup(base);
   536→        west.rotation.y = Math.PI / 2;
   537→        west.position.set(-half, 0, 0);
   538→        group.add(west);
   539→
   540→        group.traverse(node => {
   541→            if (node.isMesh) {
   542→                node.castShadow = true;
   543→                node.receiveShadow = true;
   544→            }
   545→        });
   546→
   547→        // Skaliere Wand-Höhe auf gewünschte wallHeight
   548→        const currentHeight = getBoundingSize(group).y;
   549→        const scaleFactor = wallHeight / Math.max(currentHeight, 0.0001);
   550→        group.scale.y *= scaleFactor;
   551→
   552→        // WICHTIG: Wände mit UNTERSEITE auf Y=0 (Boden-Oberseite)
   553→        const box = new THREE.Box3().setFromObject(group);
   554→        group.position.y = -box.min.y;
   555→
   556→        applyEntryTransform(group, entry);
   557→        return group;
   558→    }
   559→
   560→    function buildProp(entry) {
   561→        const instance = makeModelInstance(entry);
   562→        if (!instance) return null;
   563→        adjustToGround(instance);
   564→        applyEntryTransform(instance, entry);
   565→        return instance;
   566→    }
   567→
   568→    function makeModelInstance(entry) {
   569→        if (!entry || !entry.model || !window.KayKitLoader) return null;
   570→        if (!KayKitLoader.hasModel || !KayKitLoader.hasModel(entry.model)) return null;
   571→        const source = KayKitLoader.getModel(entry.model);
   572→        if (!source) return null;
   573→        const wrapper = new THREE.Group();
   574→        const clone = cloneObject(source);
   575→        wrapper.add(clone);
   576→        applyTint(wrapper, entry.tint);
   577→        wrapper.traverse(node => {
   578→            if (node.isMesh) {
   579→                node.castShadow = true;
   580→                node.receiveShadow = true;
   581→            }
   582→        });
   583→        return wrapper;
   584→    }
   585→
   586→    function cloneObject(object) {
   587→        if (THREE.SkeletonUtils && typeof THREE.SkeletonUtils.clone === 'function') {
   588→            return THREE.SkeletonUtils.clone(object);
   589→        }
   590→        return object.clone(true);
   591→    }
   592→
   593→    function cloneGroup(group) {
   594→        const copy = group.clone(true);
   595→        copy.traverse(node => {
   596→            if (node.isMesh) {
   597→                node.castShadow = true;
   598→                node.receiveShadow = true;
   599→            }
   600→        });
   601→        return copy;
   602→    }
   603→
   604→    function scaleUniformToSpan(group, span) {
   605→        const size = getBoundingSize(group);
   606→        const max = Math.max(size.x, size.z);
   607→        if (!max || !isFinite(max)) return;
   608→        const factor = span / max;
   609→        group.scale.multiplyScalar(factor);
   610→    }
   611→
   612→    function scaleAxisToSpan(group, axis, span) {
   613→        const size = getBoundingSize(group);
   614→        const axisSize = axis === 'z' ? size.z : size.x;
   615→        if (!axisSize || !isFinite(axisSize)) return;
   616→        const factor = span / axisSize;
   617→        if (axis === 'z') {
   618→            group.scale.z *= factor;
   619→        } else {
   620→            group.scale.x *= factor;
   621→        }
   622→    }
   623→
   624→    function getBoundingSize(group) {
   625→        const box = new THREE.Box3().setFromObject(group);
   626→        const size = new THREE.Vector3();
   627→        box.getSize(size);
   628→        return size;
   629→    }
   630→
   631→    function adjustToGround(group) {
   632→        const box = new THREE.Box3().setFromObject(group);
   633→        const offsetY = box.min.y;
   634→        group.position.y -= offsetY;
   635→    }
   636→
   637→    function applyTint(group, tint) {
   638→        const hex = parseColor(tint);
   639→        if (hex === null) return;
   640→        group.traverse(node => {
   641→            if (node.isMesh) {
   642→                const material = node.material;
   643→                if (Array.isArray(material)) {
   644→                    material.forEach(mat => mat && mat.color && mat.color.set(hex));
   645→                } else if (material && material.color) {
   646→                    material.color.set(hex);
   647→                }
   648→            }
   649→        });
   650→    }
   651→
   652→    function applyEntryTransform(group, entry) {
   653→        if (!entry) return;
   654→
   655→        if (typeof entry.scale === 'number') {
   656→            group.scale.multiplyScalar(entry.scale);
   657→        } else if (Array.isArray(entry.scale)) {
   658→            const [sx = 1, sy = 1, sz = 1] = entry.scale;
   659→            group.scale.x *= sx;
   660→            group.scale.y *= sy;
   661→            group.scale.z *= sz;
   662→        }
   663→
   664→        if (Array.isArray(entry.rotation)) {
   665→            const [rx = 0, ry = 0, rz = 0] = entry.rotation;
   666→            group.rotation.set(rx, ry, rz);
   667→        }
   668→
   669→        if (Array.isArray(entry.position)) {
   670→            const [px = 0, py = 0, pz = 0] = entry.position;
   671→            // Nur X und Z setzen, Y wird durch adjustToGround() bestimmt
   672→            group.position.x += px;
   673→            group.position.z += pz;
   674→            // Y-Offset wird NACH adjustToGround angewendet
   675→            if (py !== 0) {
   676→                group.position.y += py;
   677→            }
   678→        }
   679→
   680→        // adjustToGround wurde bereits vorher aufgerufen, nicht nochmal!
   681→        // adjustToGround(group);
   682→    }
   683→
   684→    function parseColor(value) {
   685→        if (typeof value === 'number') return value;
   686→        if (typeof value === 'string') {
   687→            try {
   688→                return new THREE.Color(value).getHex();
   689→            } catch (error) {
   690→                return null;
   691→            }
   692→        }
   693→        return null;
   694→    }
