   698→            ? PRIVATE_PALETTE
   699→            : roomPalette
   700→            ? { ...DEFAULT_PALETTE, ...roomPalette }
   701→            : DEFAULT_PALETTE;
   702→
   703→        const palette = { ...DEFAULT_PALETTE };
   704→        Object.keys(paletteSource).forEach(key => {
   705→            const value = paletteSource[key];
   706→            palette[key] = typeof value === 'string' ? parseColor(value) || palette[key] : value;
   707→        });
   708→
   709→        scene.background = new THREE.Color(palette.background);
   710→        if (!scene.fog) {
