   718→
   719→        dirLight.color.setHex(palette.dir);
   720→        dirLight.intensity = palette.dirIntensity;
   721→
   722→        pointLight1.color.setHex(palette.primary);
   723→        pointLight2.color.setHex(palette.secondary);
   724→
   725→        if (baseFloor && usingFallbackRoom) {
