   754→                adjustToGround(characterGroup);
   755→                scene.add(characterGroup);
   756→                attachStaffToCharacter();
   757→                characterReady = true;
   758→                console.log('✅ Skeleton_Mage geladen, Füße auf Y=0');
   759→            },
   760→            undefined,
   761→            error => {
   762→                console.warn('Scene3D: failed to load Skeleton_Mage model', error);
   763→            }
   764→        );
   765→    }
   766→
   767→    function attachStaffToCharacter() {
   768→        if (!characterGroup || !window.KayKitLoader || !KayKitLoader.getModel) {
   769→            return;
   770→        }
   771→        if (characterGroup.getObjectByName('najika_staff')) {
   772→            return;
   773→        }
   774→        const wandModel = KayKitLoader.getModel(
   775→            'KayKit_Adventurers_1.0_FREE/KayKit_Adventurers_1.0_FREE/Assets/gltf/wand.gltf'
   776→        );
   777→        if (!wandModel) {
   778→            return;
   779→        }
   780→        const wand = cloneObject(wandModel);
   781→        wand.name = 'najika_staff';
   782→        adjustToGround(wand);
   783→        wand.scale.multiplyScalar(1.3);
   784→        wand.rotation.set(0, Math.PI / 2, Math.PI / 8);
   785→        wand.position.set(0.4, 1.1, -0.2);
   786→        characterGroup.add(wand);
   787→    }
   788→
   789→    function updateCharacter(delta) {
   790→        if (!characterGroup) return;
   791→
   792→        // Input relativ zum Spieler (lokal)
   793→        let forward = 0;
   794→        let right = 0;
   795→
   796→        // Third & Orbit: W/S vertauscht | First: A/D vertauscht
   797→        if (cameraMode === CAMERA_MODES.FIRST) {
   798→            // FIRST: A/D vertauscht
   799→            if (activeKeys.has('KeyW') || activeKeys.has('ArrowUp')) forward += 1;
   800→            if (activeKeys.has('KeyS') || activeKeys.has('ArrowDown')) forward -= 1;
   801→            if (activeKeys.has('KeyA') || activeKeys.has('ArrowLeft')) right += 1;  // VERTAUSCHT
   802→            if (activeKeys.has('KeyD') || activeKeys.has('ArrowRight')) right -= 1;  // VERTAUSCHT
   803→        } else {
   804→            // THIRD & ORBIT: W/S vertauscht
   805→            if (activeKeys.has('KeyW') || activeKeys.has('ArrowUp')) forward -= 1;  // VERTAUSCHT
   806→            if (activeKeys.has('KeyS') || activeKeys.has('ArrowDown')) forward += 1;  // VERTAUSCHT
   807→            if (activeKeys.has('KeyA') || activeKeys.has('ArrowLeft')) right -= 1;
   808→            if (activeKeys.has('KeyD') || activeKeys.has('ArrowRight')) right += 1;
   809→        }
   810→
   811→        if (forward !== 0 || right !== 0) {
   812→            // FORTNITE-Style: WASD relativ zur KAMERA (orbitYaw)
   813→            const inputAngle = Math.atan2(right, forward);
   814→            const worldAngle = orbitYaw + inputAngle;
   815→
   816→            // Bewegungsvektor in Weltkoordinaten
   817→            const moveX = Math.sin(worldAngle);
   818→            const moveZ = Math.cos(worldAngle);
   819→
   820→            const speed = CHARACTER_SPEED * (cameraMode === CAMERA_MODES.FIRST ? 0.9 : 1);
   821→            characterGroup.position.x += moveX * speed * delta;
   822→            characterGroup.position.z += moveZ * speed * delta;
   823→            clampCharacterToRoom(characterGroup.position);
   824→
   825→            // Charakter dreht sich in Bewegungsrichtung
   826→            characterHeading = worldAngle;
   827→            characterGroup.rotation.y = characterHeading;
   828→        }
   829→    }
   830→
   831→    function clampCharacterToRoom(position) {
   832→        const limit = Math.max(8, currentRoomSpan / 2 - CLAMP_PADDING);
   833→        position.x = clamp(position.x, -limit, limit);
   834→        position.z = clamp(position.z, -limit, limit);
   835→    }
   836→
   837→    function getCameraTarget() {
   838→        if (characterGroup) {
   839→            return characterGroup.position.clone().add(new THREE.Vector3(0, CHARACTER_HEIGHT * 0.85, 0));
   840→        }
   841→        return new THREE.Vector3(0, 0, 0);
   842→    }
   843→
   844→    function updateCamera(delta) {
   845→        if (!camera) return;
   846→
   847→        const target = getCameraTarget();
   848→        const cosPitch = Math.cos(orbitPitch);
   849→        const sinPitch = Math.sin(orbitPitch);
   850→        const cosYaw = Math.cos(orbitYaw);
   851→        const sinYaw = Math.sin(orbitYaw);
   852→
   853→        if (cameraMode === CAMERA_MODES.ORBIT || !characterGroup) {
   854→            // ORBIT Mode: Freie Kamera-Steuerung
   855→            const offset = new THREE.Vector3(
   856→                sinYaw * cosPitch,
   857→                sinPitch,
   858→                cosYaw * cosPitch
   859→            ).multiplyScalar(orbitDistance);
   860→            camera.position.copy(target).add(offset);
   861→            camera.lookAt(target);
   862→        } else if (cameraMode === CAMERA_MODES.THIRD) {
   863→            // THIRD: Kamera wie Orbit, nur näher (Fortnite-Style: Maus steuert Kamera)
   864→            const distance = 12;
   865→            const height = 4;
   866→            const offset = new THREE.Vector3(
   867→                sinYaw * cosPitch * distance,
   868→                height + sinPitch * distance * 0.5,
   869→                cosYaw * cosPitch * distance
   870→            );
   871→            camera.position.copy(target).add(offset);
   872→            camera.lookAt(target);
   873→        } else if (cameraMode === CAMERA_MODES.FIRST) {
   874→            // FIRST: Kamera DIREKT am Kopf (Augen), Blickrichtung = orbitYaw/Pitch
   875→            const eyeHeight = CHARACTER_HEIGHT * 0.85;
   876→
   877→            // Kamera DIREKT am Kopf (keine Offset-Berechnung nötig)
   878→            camera.position.set(
   879→                characterGroup.position.x,
   880→                characterGroup.position.y + eyeHeight,
   881→                characterGroup.position.z
   882→            );
   883→
   884→            // Blickrichtung folgt MAUS (orbitYaw und orbitPitch)
   885→            const lookDistance = 10;
   886→            const lookTarget = new THREE.Vector3(
   887→                camera.position.x + sinYaw * cosPitch * lookDistance,
   888→                camera.position.y + sinPitch * lookDistance,
   889→                camera.position.z + cosYaw * cosPitch * lookDistance
   890→            );
   891→            camera.lookAt(lookTarget);
   892→        }
   893→    }
   894→
   895→    function faceCharacter() {
   896→        if (!characterGroup || !camera) return;
   897→        const dx = camera.position.x - characterGroup.position.x;
   898→        const dz = camera.position.z - characterGroup.position.z;
   899→        characterHeading = Math.atan2(dx, dz);
   900→        characterGroup.rotation.y = characterHeading;
   901→    }
