   903→    async function toggleWebcam(videoElement) {
   904→        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
   905→            alert('Webcam wird nicht unterstützt.');
   906→            return false;
   907→        }
   908→        if (webcamStream) {
   909→            webcamStream.getTracks().forEach(track => track.stop());
   910→            webcamStream = null;
