   917→        try {
   918→            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
   919→            webcamStream = stream;
   920→            webcamElement = videoElement;
   921→            webcamElement.srcObject = stream;
   922→            await webcamElement.play();
   923→            return true;
   924→        } catch (error) {
   925→            console.warn('Scene3D: webcam access failed', error);
   926→            alert('Webcam konnte nicht gestartet werden.');
   927→            return false;
   928→        }
   929→    }
