function toggleEquipmentPanel() {
    const content = document.getElementById('equipmentContent');
    const toggle = document.getElementById('equipmentToggle');
    if (content.style.display === 'none') {
        content.style.display = 'block';
        toggle.textContent = '▼';
    } else {
        content.style.display = 'none';
        toggle.textContent = '▶';
    }
}

async function fetchNajikaStatus() {
    try {
        const data = await api('/api/najika/status');
        updateNajikaHUD(data);
    } catch (error) {
        console.warn('Najika-Status konnte nicht geladen werden.', error);
    }
}

