# 1. Blur Dropdown wenn Canvas geklickt wird
OLD_INSTALL_HANDLERS = """    function installEventHandlers() {
        window.addEventListener('resize', onWindowResize, false);
        window.addEventListener('keydown', onKeyDown, false);
        window.addEventListener('keyup', onKeyUp, false);

        const canvas = renderer.domElement;
        orbitCanvas = canvas;
        canvas.style.touchAction = 'none';
        canvas.addEventListener('pointerdown', onPointerDown, { passive: false });"""

NEW_INSTALL_HANDLERS = """    function installEventHandlers() {
        window.addEventListener('resize', onWindowResize, false);
        window.addEventListener('keydown', onKeyDown, false);
        window.addEventListener('keyup', onKeyUp, false);

        const canvas = renderer.domElement;
        orbitCanvas = canvas;
        canvas.style.touchAction = 'none';

        // BLUR alle Dropdowns/Inputs wenn Canvas geklickt wird
        canvas.addEventListener('pointerdown', (e) => {
            const roomDropdown = document.getElementById('room');
            if (roomDropdown) roomDropdown.blur();
            const dungeonDropdown = document.getElementById('dungeonLevel');
            if (dungeonDropdown) dungeonDropdown.blur();
            // Blur aktives Element generell
            if (document.activeElement && document.activeElement.tagName === 'SELECT') {
                document.activeElement.blur();
            }
        });

        canvas.addEventListener('pointerdown', onPointerDown, { passive: false });"""

if OLD_INSTALL_HANDLERS in content:
