        // BLUR Dropdown wenn WASD gedrueckt wird
        if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.code)) {
            const roomDropdown = document.getElementById('room');
            if (roomDropdown && document.activeElement === roomDropdown) {
                roomDropdown.blur();
            }
        }

        activeKeys.add(event.code);
        // F-Taste: Najika dreht sich zum Spieler
        if (event.code === 'KeyF') {
            faceCharacter();
        }
    }"""

    if OLD_KEYDOWN in content:
        content = content.replace(OLD_KEYDOWN, NEW_KEYDOWN)
        print("[OK] KeyDown Blur Handler hinzugefuegt!")
    else:
        print("[ERROR] Keine passende Stelle gefunden!")

with open(HTML, 'w', encoding='utf-8') as f:
